  | { success: true; data: any[]; message: string }
  | { success: false; message: string };

export type DeleteContextResult =
  | { success: true; message: string }
  | { success: false; message: string };

export type AddToMemoryResult =
  | { success: true; message: string }
  | { success: false; message: string };

